// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/info", wrapper.GetInfo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/auth/session", wrapper.GetSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/setup", wrapper.SetupAdmin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/display", wrapper.GetDisplaySettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/display", wrapper.UpdateDisplaySettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/kiosk/state", wrapper.GetKioskState)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/weather", wrapper.GetWeatherSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/weather", wrapper.UpdateWeatherSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/wifi", wrapper.GetWifiSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/wifi", wrapper.UpdateWifiSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/layout", wrapper.GetLayoutSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/layout", wrapper.UpdateLayoutSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/modules", wrapper.ListModules)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/dashboard/layout", wrapper.GetDashboardLayout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/dashboard/weather", wrapper.GetDashboardWeather)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/dashboard/wifi", wrapper.GetDashboardWifi)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/settings/calendar", wrapper.GetCalendarSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/settings/calendar", wrapper.UpdateCalendarSettings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/settings/calendar/preview", wrapper.PreviewCalendar)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/dashboard/calendar/{sectionId}", wrapper.GetDashboardCalendarSection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/icons", wrapper.ListIcons)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/icons", wrapper.UploadIcon)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/icons/{id}", wrapper.DeleteIcon)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/icons/{id}/file", wrapper.GetIconFile)

	return m
}

